support.py.old:
def root_guard(path,pinned_path,cap,wall_limit=3600):
    proof=load(path);r=proof["request"]
    if not os.environ.get("SLURM_JOB_ID") or socket.gethostname().split(".")[0]!="compute-0-20":
        raise ValueError("STREAMING_LABEL_ANALYSIS_REQUIRES_SLURM_COMPUTE20")
    if int(os.environ.get("SLURM_CPUS_PER_TASK","0"))<16 or r["cpus"]<16 or r["kind"]!="analysis":
        raise ValueError("REAL_16_CPU_ANALYSIS_REQUIRED")
    if r["node"]!="compute-0-20" or r["wall_seconds"]>wall_limit or r["memory_gib"]<32:
        raise ValueError("ROOT_RESOURCE_REQUEST_DIFFERS")
    if ref(pinned_path) not in r["source_references"] or r["estimated_peak_output_bytes"]<cap:
        raise ValueError("ROOT_SOURCE_PIN_OR_STORAGE_ESTIMATE_DIFFERS")
    age=time.time()-datetime.fromisoformat(proof["observed_at"]).timestamp()
    if not 0<=age<=3600:
        raise ValueError("ROOT_QUOTA_RESOURCE_PREFLIGHT_STALE")
    real=re.search(r"(?:^|\s)RealMemory=(\d+)(?:\s|$)",proof["node_metadata"])
    if real is None or not isinstance(proof["existing_jobs_all_users"],list):
        raise ValueError("ALL_USERS_DECLARED_MEMORY_EVIDENCE_MISSING")
    if proof["committed_memory_mib"]+r["memory_gib"]*1024>int(real[1])*.85:
        raise ValueError("DECLARED_MEMORY_ABOVE_85_PERCENT")
    if proof["account_free_bytes"]-cap<200_000_000_000:
        raise ValueError("STOP_QUOTA_WOULD_REMAIN_BELOW_200GB")
    return proof

