def root_guard(path,pinned_path,cap,wall_limit=3600):
    return _cpu_root_guard(path,pinned_path,cap,wall_limit)


def checkpoint_iter(iterable):
    iterator=iter(iterable)
    while True:
        checkpoint()
        try:
            item=next(iterator)
        except StopIteration:
            return
        yield item
